import { GetGranteesBodyResponse, GranteesResultBodyResponse } from "../types/schema/grantee.js";
import { prepareRequestHeaders } from "../utils/headers.js";
import { http } from "../utils/http.js";
const granteeEndpoint = 'grantee';
/** Creates grantees for a postage batch. */
export async function createGrantees(requestOptions, batchId, publicKeys) {
  const response = await http(requestOptions, {
    method: 'post',
    url: granteeEndpoint,
    data: {
      grantees: publicKeys.map(x => x.toCompressedHex())
    },
    headers: prepareRequestHeaders(batchId),
    responseType: 'json'
  });
  const body = GranteesResultBodyResponse.parse(response.data);
  return {
    status: response.status,
    statusText: response.statusText,
    ref: body.ref,
    historyref: body.historyref
  };
}
/** Retrieves the grantees for a given reference. */
export async function getGrantees(requestOptions, reference) {
  const response = await http(requestOptions, {
    method: 'get',
    url: `${granteeEndpoint}/${reference}`,
    responseType: 'json'
  });
  return {
    status: response.status,
    statusText: response.statusText,
    grantees: GetGranteesBodyResponse.parse(response.data)
  };
}
/** Updates the grantees of a specific reference and history. */
export async function patchGrantees(requestOptions, batchId, reference, history, publicKeys) {
  const response = await http(requestOptions, {
    method: 'patch',
    url: `${granteeEndpoint}/${reference}`,
    data: {
      add: publicKeys.add.map(x => x.toCompressedHex()),
      revoke: publicKeys.revoke.map(x => x.toCompressedHex())
    },
    headers: {
      ...prepareRequestHeaders(batchId),
      'swarm-act-history-address': history.toHex()
    },
    responseType: 'json'
  });
  const body = GranteesResultBodyResponse.parse(response.data);
  return {
    status: response.status,
    statusText: response.statusText,
    ref: body.ref,
    historyref: body.historyref
  };
}